// Cost-nonincreasing spatial relaxation for single-stage bodies and full ordinary covers.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Web.Script.Serialization;
public struct State:IEquatable<State>{public ulong gone,ghost;public bool Equals(State s){return gone==s.gone&&ghost==s.ghost;}public override bool Equals(object s){return s is State&&Equals((State)s);}public override int GetHashCode(){unchecked{return (int)(gone^(gone>>32)^ghost*0x9e3779b1UL^(ghost>>32));}}}
public struct Mask{public ulong lo,hi;public static Mask From(long[] a){return new Mask{lo=(ulong)(uint)a[0]|((ulong)(uint)a[1]<<32),hi=(ulong)(uint)a[2]|((ulong)(uint)a[3]<<32)};}public static Mask operator |(Mask a,Mask b){return new Mask{lo=a.lo|b.lo,hi=a.hi|b.hi};}public bool Overlap(Mask b){return(lo&b.lo)!=0||(hi&b.hi)!=0;}}
public class PoseInput{public long[] mask;public int[] exits,neighbors;}public class BodyInput{public int layers,ice,reveal;public PoseInput[] poses;}public class CoverInput{public int count;public long[] mask;}public class Input{public int floor,maxMilliseconds,maxStates,goalClears;public int[] initial;public BodyInput[] blocks;public CoverInput[] covers;}
public class Pose{public Mask mask;public int[] exits,neighbors;}public class Body{public int ice,reveal,initial,gate;public Pose[] poses;}public class Cover{public int count;public Mask mask;}
public class BudgetStop:Exception{public BudgetStop(string s):base(s){}}
public class Solver{
 readonly Input input;readonly Body[] bodies;readonly Cover[] covers;readonly int n;readonly ulong all;readonly Stopwatch clock=new Stopwatch();readonly int[] queue=new int[128],marks=new int[128];int marker,cost,maxClears;long explored,transitions;readonly Dictionary<State,int> seen=new Dictionary<State,int>();readonly List<State>[] buckets;
 public Solver(Input p){input=p;n=p.blocks.Length;if(n<1||n>64||p.floor<1||p.maxStates<1)throw new Exception("domain");all=n==64?ulong.MaxValue:(1UL<<n)-1;bodies=p.blocks.Select((b,i)=>{if(b.layers!=1)throw new Exception("single stage only");return new Body{ice=b.ice,reveal=b.reveal,initial=p.initial[i],gate=b.poses.Where(x=>x!=null).SelectMany(x=>x.exits).Where(x=>x>=0).DefaultIfEmpty(int.MaxValue).Min(),poses=b.poses.Select(x=>x==null?null:new Pose{mask=Mask.From(x.mask),exits=x.exits,neighbors=x.neighbors}).ToArray()};}).ToArray();covers=p.covers.Select(c=>new Cover{count=c.count,mask=Mask.From(c.mask)}).ToArray();buckets=Enumerable.Range(0,p.floor).Select(i=>new List<State>()).ToArray();}
 static int Count(ulong a){int n=0;while(a!=0){a&=a-1;n++;}return n;}
 bool Active(Body b,int clears){return clears>=b.reveal+b.ice;}
 Mask Occupied(State s,int clears,int skip){Mask m=new Mask();foreach(Cover c in covers)if(clears<c.count)m|=c.mask;for(int i=0;i<n;i++)if(i!=skip&&((s.gone|s.ghost)&(1UL<<i))==0&&clears>=bodies[i].reveal)m|=bodies[i].poses[bodies[i].initial].mask;return m;}
 bool CanClear(State s,int i,int clears){Body b=bodies[i];if(clears<b.gate)return false;if((s.ghost&(1UL<<i))!=0)return true;Mask occupied=Occupied(s,clears,i);int head=0,tail=1;queue[0]=b.initial;marker++;marks[b.initial]=marker;while(head<tail){int at=queue[head++];Pose p=b.poses[at];if(p.exits.Any(x=>x>=0&&x<=clears))return true;foreach(int to in p.neighbors)if(marks[to]!=marker&&!b.poses[to].mask.Overlap(occupied)){marks[to]=marker;queue[tail++]=to;}}return false;}
 State Normalize(State s){for(;;){int clears=Count(s.gone);if(clears>=input.goalClears)return s;bool changed=false;for(int i=0;i<n;i++)if((s.gone&(1UL<<i))==0&&Active(bodies[i],clears)&&CanClear(s,i,clears)){s.gone|=1UL<<i;s.ghost&=~(1UL<<i);changed=true;break;}if(!changed)return s;}}
 public object Run(){clock.Start();State first=Normalize(new State());seen[first]=0;buckets[0].Add(first);string stop=null;int? minimum=null;try{for(cost=0;cost<input.floor;cost++){for(int j=0;j<buckets[cost].Count;j++){if(clock.ElapsedMilliseconds>=input.maxMilliseconds)throw new BudgetStop("deadline");State s=buckets[cost][j];if(seen[s]<cost)continue;explored++;int clears=Count(s.gone);maxClears=Math.Max(maxClears,clears);if(clears>=input.goalClears){minimum=cost;throw new BudgetStop("shortcut");}for(int i=0;i<n;i++){if(((s.gone|s.ghost)&(1UL<<i))!=0||!Active(bodies[i],clears)||cost+1>=input.floor)continue;transitions++;State next=s;next.ghost|=1UL<<i;next=Normalize(next);int old;if(seen.TryGetValue(next,out old)&&old<=cost+1)continue;if(seen.Count>=input.maxStates)throw new BudgetStop("max-states");seen[next]=cost+1;buckets[cost+1].Add(next);}}}}catch(BudgetStop e){stop=e.Message;}bool unknown=stop=="deadline"||stop=="max-states";return new{status=unknown?"unknown":minimum.HasValue?"relaxed-shortcut":"threshold-proven",floor=input.floor,goalClears=input.goalClears,frontierCost=cost,minimum,exploredStates=explored,discoveredStates=seen.Count,transitions,maxClears,elapsedMilliseconds=clock.ElapsedMilliseconds,termination=stop??"below-threshold-exhausted"};}
 public static int Main(string[] args){try{var json=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};File.WriteAllText(args[1],json.Serialize(new Solver(json.Deserialize<Input>(File.ReadAllText(args[0]))).Run()));return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
